#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricImpedance; 8] = [
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Ohm),
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Nanoohm),
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Microohm),
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Milliohm),
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Kiloohm),
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Megaohm),
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Gigaohm),
        ElectricImpedance::const_new(1234.5, ElectricImpedanceUnit::Teraohm),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ElectricImpedanceUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricImpedance::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricImpedanceUnit::ALL {
            assert_eq!(
                ElectricImpedance::const_new(v, unit).as_base().to_bits(),
                ElectricImpedance::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricImpedance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricImpedance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricImpedanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricImpedance::from_base(0.0).auto_unit().unit,
        ElectricImpedanceUnit::Ohm
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Ω".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Ohm)
    );
    assert_eq!(
        format!("2.5 {}", "Ω").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Ohm))
    );
    assert_eq!(
        "nΩ".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Nanoohm)
    );
    assert_eq!(
        format!("2.5 {}", "nΩ").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Nanoohm))
    );
    assert_eq!(
        "µΩ".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Microohm)
    );
    assert_eq!(
        format!("2.5 {}", "µΩ").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Microohm))
    );
    assert_eq!(
        "mΩ".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Milliohm)
    );
    assert_eq!(
        format!("2.5 {}", "mΩ").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Milliohm))
    );
    assert_eq!(
        "kΩ".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Kiloohm)
    );
    assert_eq!(
        format!("2.5 {}", "kΩ").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Kiloohm))
    );
    assert_eq!(
        "MΩ".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Megaohm)
    );
    assert_eq!(
        format!("2.5 {}", "MΩ").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Megaohm))
    );
    assert_eq!(
        "GΩ".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Gigaohm)
    );
    assert_eq!(
        format!("2.5 {}", "GΩ").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Gigaohm))
    );
    assert_eq!(
        "TΩ".parse::<ElectricImpedanceUnit>(),
        Ok(ElectricImpedanceUnit::Teraohm)
    );
    assert_eq!(
        format!("2.5 {}", "TΩ").parse::<ElectricImpedance>(),
        Ok(ElectricImpedance::new(2.5, ElectricImpedanceUnit::Teraohm))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricImpedance>(),
        Err(ParseError::UnknownUnit)
    );
}

